import base64, zlib, sys

raw = open('/tmp/w/baseline.msg').read()
b64 = ''.join(l for l in raw.splitlines() if not l.startswith('---') and l.strip())
data = base64.b64decode(b64)

def parse(d):
    pkts = []
    i = 0
    while i < len(d):
        b = d[i]; tag = b & 0x3f; j = i+1
        l = d[j]; j+=1
        if 192 <= l < 224: l = ((l-192)<<8) + d[j] + 192; j+=1
        elif l == 255: l = int.from_bytes(d[j:j+4],'big'); j+=4
        pkts.append((tag, d[i:j], d[j:j+l]))
        i = j+l
    return pkts

def hdr_new(tag, body):
    l = len(body)
    if l < 192: return bytes([0xc0|tag, l])
    elif l < 8384:
        v = l - 192
        return bytes([0xc0|tag, 192 + (v>>8), v & 0xff])
    else:
        return bytes([0xc0|tag, 255]) + l.to_bytes(4,'big')

def hdr_old(tag, body):
    l = len(body)
    if l < 256: return bytes([(tag<<2)|0x00, l])
    elif l < 65536: return bytes([(tag<<2)|0x01]) + l.to_bytes(2,'big')
    else: return bytes([(tag<<2)|0x02]) + l.to_bytes(4,'big')

pkts = parse(data)
ops = pkts[0]; lit = pkts[1]; sig = pkts[2]
print('OPS body:', ops[2].hex())
print('LIT body:', lit[2].hex())
print('SIG body head:', sig[2][:6].hex())
EOF
python3 /tmp/w/build.py

